#include "FirewallRx_FirewallRx.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void FirewallRx_FirewallRx_initialize(void);
void FirewallRx_FirewallRx_notify(microkit_channel channel);
void FirewallRx_FirewallRx_timeTriggered(void);

volatile sb_queue_SW_StructuredEthernetMessage_i_1_t *EthernetFramesRxOut_queue_1;
volatile sb_queue_SW_AttackStatus_1_t *AttackStatusRx_queue_1;
volatile sb_queue_SW_StructuredEthernetMessage_i_1_t *EthernetFramesRxIn_queue_1;
sb_queue_SW_StructuredEthernetMessage_i_1_Recv_t EthernetFramesRxIn_recv_queue;
volatile sb_queue_SW_Mode_1_t *CurrentMode_queue_1;
sb_queue_SW_Mode_1_Recv_t CurrentMode_recv_queue;

#define PORT_FROM_MON 0

bool put_EthernetFramesRxOut(const SW_StructuredEthernetMessage_i *data) {
  sb_queue_SW_StructuredEthernetMessage_i_1_enqueue((sb_queue_SW_StructuredEthernetMessage_i_1_t *) EthernetFramesRxOut_queue_1, (SW_StructuredEthernetMessage_i *) data);

  return true;
}

bool put_AttackStatusRx(const SW_AttackStatus *data) {
  sb_queue_SW_AttackStatus_1_enqueue((sb_queue_SW_AttackStatus_1_t *) AttackStatusRx_queue_1, (SW_AttackStatus *) data);

  return true;
}

bool EthernetFramesRxIn_is_empty(void) {
  return sb_queue_SW_StructuredEthernetMessage_i_1_is_empty(&EthernetFramesRxIn_recv_queue);
}

bool get_EthernetFramesRxIn_poll(sb_event_counter_t *numDropped, SW_StructuredEthernetMessage_i *data) {
  return sb_queue_SW_StructuredEthernetMessage_i_1_dequeue((sb_queue_SW_StructuredEthernetMessage_i_1_Recv_t *) &EthernetFramesRxIn_recv_queue, numDropped, data);
}

bool get_EthernetFramesRxIn(SW_StructuredEthernetMessage_i *data) {
  sb_event_counter_t numDropped;
  return get_EthernetFramesRxIn_poll (&numDropped, data);
}

uintmax_t get_EthernetFramesRxIn_num_invalid(void) {
  return sb_queue_SW_StructuredEthernetMessage_i_1_numInvalid((sb_queue_SW_StructuredEthernetMessage_i_1_Recv_t *) &EthernetFramesRxIn_recv_queue);
}

SW_Mode last_CurrentMode_payload;

bool get_CurrentMode(SW_Mode *data) {
  sb_event_counter_t numDropped;
  SW_Mode fresh_data;
  bool isFresh = sb_queue_SW_Mode_1_dequeue((sb_queue_SW_Mode_1_Recv_t *) &CurrentMode_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_CurrentMode_payload = fresh_data;
  }
  *data = last_CurrentMode_payload;
  return isFresh;
}

uintmax_t get_CurrentMode_num_invalid(void) {
  return sb_queue_SW_Mode_1_numInvalid((sb_queue_SW_Mode_1_Recv_t *) &CurrentMode_recv_queue);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_SW_StructuredEthernetMessage_i_1_init((sb_queue_SW_StructuredEthernetMessage_i_1_t *) EthernetFramesRxOut_queue_1);

  sb_queue_SW_AttackStatus_1_init((sb_queue_SW_AttackStatus_1_t *) AttackStatusRx_queue_1);

  sb_queue_SW_StructuredEthernetMessage_i_1_Recv_init(&EthernetFramesRxIn_recv_queue, (sb_queue_SW_StructuredEthernetMessage_i_1_t *) EthernetFramesRxIn_queue_1);

  sb_queue_SW_Mode_1_Recv_init(&CurrentMode_recv_queue, (sb_queue_SW_Mode_1_t *) CurrentMode_queue_1);

  FirewallRx_FirewallRx_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      FirewallRx_FirewallRx_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      FirewallRx_FirewallRx_notify(channel);
  }
}
